  var ETK_LOUPE_ZOOM = 2.5;
  var ETK_LOUPE_PX = 220;
  function etkOpenLightbox(url, name, btnr, chassisId) {
    if (typeof openModal !== "function") return;
    const m = openModal(
      `<div class="etk-lightbox">
       <div class="etk-lightbox-head">
         <span class="etk-lightbox-title">${esc(name)}</span>
         <span class="etk-lightbox-hint">Move over the drawing to magnify</span>
         <button type="button" class="etk-lightbox-close" aria-label="Close">\xD7</button>
       </div>
       <div class="etk-lightbox-plate">
         <img class="etk-lightbox-img" alt="${esc(name)}" src="${esc(url)}" />
         <div class="etk-loupe" hidden></div>
       </div>
     </div>`,
    );
    const box = m.overlay.querySelector(".etk-lightbox");
    const img = box.querySelector(".etk-lightbox-img");
    const loupe = box.querySelector(".etk-loupe");
    box.querySelector(".etk-lightbox-close").onclick = () => m.close();
    let dropHs = null;
    let carry = null;
    const paneTable = document.querySelector(".etk-parts");
    if (btnr && chassisId && typeof loadEtkHotspots === "function") {
      loadEtkHotspots(chassisId).then((hs) => {
        if (!box.isConnected) return;
        const rects = hs && hs.bt ? hs.bt[btnr] : null;
        if (!rects || !rects.length) return;
        if (etkDropHotspots) etkDropHotspots();
        etkDropHotspots = null;
        dropHs = etkAttachHotspots({
          img,
          layerHost: box.querySelector(".etk-lightbox-plate"),
          hotspots: rects,
          table: paneTable,
          scrollRows: false,
          // a pick in the enlarged view answers the question and leaves: the
          // view closes and the pane behind opens on that callout, row in view
          onPick: (pos) => {
            carry = pos;
            m.close();
          },
        });
      });
    }
    if (typeof MutationObserver === "function") {
      const gone = new MutationObserver(() => {
        if (box.isConnected) return;
        gone.disconnect();
        if (!dropHs) return;
        dropHs();
        dropHs = null;
        etkRestorePaneHotspots(btnr, chassisId, carry);
      });
      gone.observe(document.body, { childList: true });
    }
    loupe.style.width = loupe.style.height = ETK_LOUPE_PX + "px";
    loupe.style.backgroundImage = `url("${url}")`;
    const plate = box.querySelector(".etk-lightbox-plate");
    plate.onpointermove = (ev) => {
      const r = img.getBoundingClientRect();
      const pr = plate.getBoundingClientRect();
      if (!r.width || !r.height) return;
      const fx = (ev.clientX - r.left) / r.width;
      const fy = (ev.clientY - r.top) / r.height;
      if (fx < 0 || fx > 1 || fy < 0 || fy > 1) {
        loupe.hidden = true;
        return;
      }
      const bw = r.width * ETK_LOUPE_ZOOM;
      const bh = r.height * ETK_LOUPE_ZOOM;
      loupe.hidden = false;
      loupe.style.left = ev.clientX - pr.left - ETK_LOUPE_PX / 2 + "px";
      loupe.style.top = ev.clientY - pr.top - ETK_LOUPE_PX / 2 + "px";
      loupe.style.backgroundSize = `${bw}px ${bh}px`;
      loupe.style.backgroundPosition = `${ETK_LOUPE_PX / 2 - fx * bw}px ${ETK_LOUPE_PX / 2 - fy * bh}px`;
      if (typeof etkLoupeMarks === "function")
        etkLoupeMarks(loupe, plate, img, fx, fy, bw, bh);
    };
    plate.onpointerleave = () => {
      loupe.hidden = true;
    };
  }

  // app/renderer/screens/etk/catalogue.mjs
  var ETK_STATE = {
    variant: null,
    variantLabel: null,
    showAll: false,
    // what a VIN said about the car, for the lines' validity (lines.js): the
    // build month decides the from/up-to windows, the side and gearbox their
    // lines; a variant picked by hand has a side and gearbox, never a month
    prod: null,
    steer: null,
    auto: null,
    // the VIN the filter came from, for the URL (routeSetFiltered); null for
    // a variant picked by hand
    vin: null,
    // what the catalogue's own line filter judges by beyond the above
    // (rules.js): the type key, the plant (the VIN index does not carry it),
    // the order's option codes from the garage, and the reader's answers to
    // the conditions the catalogue asks about (element id -> '0'/'1'/'2')
    typ: null,
    werk: null,
    sa: [],
    answers: {},
  };
  function etkSetCarFacts(variant, hit) {
    const prod = hit && hit.prod ? String(hit.prod).slice(0, 6) : "";
    ETK_STATE.prod = /^\d{6}$/.test(prod) ? Number(prod) : null;
    const steer = String(
      (hit && hit.steer) || (variant && variant.steer) || "",
    );
    ETK_STATE.steer = steer === "L" || steer === "R" ? steer : null;
    const gear = String((variant && variant.gear) || "");
    ETK_STATE.auto = gear === "A" || gear === "M" ? gear : null;
    ETK_STATE.vin = hit && hit.vin ? String(hit.vin).toUpperCase() : null;
    ETK_STATE.typ = variant && variant.key ? String(variant.key) : null;
    ETK_STATE.werk = null;
    const saved =
      ETK_STATE.vin && typeof garageFindByVin === "function"
        ? garageFindByVin(ETK_STATE.vin)
        : null;
    ETK_STATE.sa = saved && Array.isArray(saved.sa) ? saved.sa.slice() : [];
    ETK_STATE.answers = {};
  }
